const schedule = $('Get row(s) in sheet4').item.json['ActivTrak Schedule'];
const baseDateFrom = $('Get row(s) in sheet').item.json.DateFrom;
const baseDateTo = $('Get row(s) in sheet').item.json.DateTo;

if (!schedule) throw new Error('ActivTrak Schedule is missing');
if (!baseDateFrom) throw new Error('Filter dateFrom is missing');
if (!baseDateTo) throw new Error('Filter dateTo is missing');

const match = schedule.match(/(\d{1,2}:\d{2}\s*[AP]M)\s*To\s*(\d{1,2}:\d{2}\s*[AP]M)/i);
if (!match) throw new Error(`Invalid schedule format: ${schedule}`);

const timeInStr = match[1].trim();
const timeOutStr = match[2].trim();

function parse12HourTime(timeStr) {
  const match = timeStr.match(/(\d{1,2}):(\d{2})\s*([AP]M)/i);
  if (!match) throw new Error(`Invalid time format: ${timeStr}`);

  let hours = parseInt(match[1], 10);
  const minutes = parseInt(match[2], 10);
  const ampm = match[3].toUpperCase();

  if (ampm === 'AM' && hours === 12) hours = 0;
  if (ampm === 'PM' && hours !== 12) hours += 12;

  return { hours, minutes };
}

function formatToISOWithOffset(dateInput, hours, minutes, offset = '+08:00') {
  // Robustly parse the incoming date to ensure a strict YYYY-MM-DD format
  const d = new Date(dateInput);
  let datePart = String(dateInput).split('T')[0]; // Fallback string split

  // If it's a valid date, force the YYYY-MM-DD format
  if (!isNaN(d.getTime())) {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    datePart = `${year}-${month}-${day}`;
  }

  const pad = (n) => String(n).padStart(2, '0');

  // Outputs strict format: 2026-04-21T08:00:00+08:00
  return `${datePart}T${pad(hours)}:${pad(minutes)}:00${offset}`;
}

const timeIn = parse12HourTime(timeInStr);
const timeOut = parse12HourTime(timeOutStr);

return {
  json: {
    ...$json,
    originalSchedule: schedule,
    timeIn: timeInStr,
    timeOut: timeOutStr,
    datefrom: formatToISOWithOffset(baseDateFrom, timeIn.hours, timeIn.minutes),
    dateto: formatToISOWithOffset(baseDateTo, timeOut.hours, timeOut.minutes),
  }
};

const returnItems = [];

for (const item of $input.all()) {
  try {
    // 1. Parse the stringified JSON inside the "data" property
    const rawData = JSON.parse(item.json.data);

    // 2. Map the parsed data to the required API structure
    const formattedData = {
      schemas: rawData.schemas || [],
      totalResults: rawData.totalResults || null,

      // Note: Source has capital 'R' (Resources), target needs lowercase 'r' (resources)
      resources: (rawData.Resources || []).map(user => {
        return {
          schemas: user.schemas || [],
          id: user.id || "",
          userName: user.userName || "",
          name: {
            familyName: user.name?.familyName || "",
            givenName: user.name?.givenName || "",
            middleName: user.name?.middleName || ""
          },
          displayName: user.displayName || "",
          emails: user.emails && user.emails.length > 0 ? user.emails : [],
          active: user.active || true,
          groups: (user.groups || []).map(group => ({
            value: group.value || "",
            display: group.display || "",
            $ref: group.$ref || "",
            type: group.type || ""
          })),
          meta: {
            resourceType: user.meta?.resourceType || "",
            created: user.meta?.created || "",
            lastModified: user.meta?.lastModified || "",
            location: user.meta?.location || "",
            version: user.meta?.version || ""
          },
          "urn:ietf:params:scim:schemas:extension:enterprise:2.0:User": {
            employeeNumber: user["urn:ietf:params:scim:schemas:extension:enterprise:2.0:User"]?.employeeNumber || ""
          },
          "urn:ietf:params:scim:schemas:extension:activtrak:2.0:User": {
            tracking: user["urn:ietf:params:scim:schemas:extension:activtrak:2.0:User"]?.tracking ?? true,
            userPrincipalNames: user["urn:ietf:params:scim:schemas:extension:activtrak:2.0:User"]?.userPrincipalNames || []
          }
        };
      })
    };

    // 3. Push the clean data back to n8n's workflow
    returnItems.push({ json: formattedData });

  } catch (error) {
    // If the JSON parsing fails, return a clear error in the node
    throw new Error(`Failed to parse data: ${error.message}`);
  }
}

return returnItems;
